import subprocess
import sys


def test_condefects_0():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='3 6\n0 2\n1 0\n0 3\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '1\n0\n2\n1\n1\n3\n2\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


def test_condefects_1():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='2 3\n1 1\n0 1\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '-1\n0\n1\n-1\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


def test_condefects_2():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='5 12\n0 1\n0 3\n1 0\n0 5\n0 2\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '1\n0\n1\n1\n1\n2\n1\n2\n2\n2\n3\n3\n4\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


